DO $$ DECLARE a uuid; b uuid; l uuid; s numeric; BEGIN BEGIN INSERT INTO public.saldos_bancarios(conta,saldo,data_saldo) VALUES ('__teste_saldo_a__',1000,current_date) RETURNING id INTO a; INSERT INTO public.saldos_bancarios(conta,saldo,data_saldo) VALUES ('__teste_saldo_b__',500,current_date) RETURNING id INTO b; INSERT INTO public.lancamentos_financeiros(tipo_fluxo,categoria,descricao,valor,data_competencia,status,conta_bancaria) VALUES ('receita','Teste','Teste transacional',100,current_date,'Pago','__teste_saldo_a__') RETURNING id INTO l; SELECT saldo INTO s FROM public.saldos_bancarios WHERE id=a; ASSERT s=1100,'entrada'; UPDATE public.lancamentos_financeiros SET valor=150 WHERE id=l; SELECT saldo INTO s FROM public.saldos_bancarios WHERE id=a; ASSERT s=1150,'edicao'; UPDATE public.lancamentos_financeiros SET conta_bancaria='__teste_saldo_b__' WHERE id=l; SELECT saldo INTO s FROM public.saldos_bancarios WHERE id=a; ASSERT s=1000,'estorno conta'; SELECT saldo INTO s FROM public.saldos_bancarios WHERE id=b; ASSERT s=650,'destino'; DELETE FROM public.lancamentos_financeiros WHERE id=l; SELECT saldo INTO s FROM public.saldos_bancarios WHERE id=b; ASSERT s=500,'exclusao'; INSERT INTO public.contas(tipo,descricao,valor,valor_pago,vencimento,status,conta_bancaria) VALUES ('pagar','Teste transacional',200,180,current_date,'pago','__teste_saldo_a__'); SELECT saldo INTO s FROM public.saldos_bancarios WHERE id=a; ASSERT s=820,'baixa com desconto'; RAISE EXCEPTION USING ERRCODE='ZX001', MESSAGE='Testes aprovados; desfazendo dados de teste'; EXCEPTION WHEN SQLSTATE 'ZX001' THEN RAISE NOTICE 'Todos os testes de saldo passaram, sem dados persistidos.'; END; END $$;